ea:AccountabilityPurpose
    a owl:Class ;
    rdfs:label "Accountability Purpose"@en ;
    rdfs:subClassOf ea:PurposeCategory .

# Bridge Definitions for Purpose

ea:PlacementAssessment
    a owl:Class ;
    rdfs:label "Placement Assessment"@en ;
    skos:altLabel "Initial Assessment"@en, "Pre-Assessment"@en, "Threshold Knowledge Test"@en ;
    rdfs:subClassOf ea:EducationalAssessment ;
    owl:equivalentClass [
        a owl:Class ;
